// Emergency Medical Technician Practice Test 1. Original questions written for Valus from the HOSA
// 2026–27 test plan, slightly harder than the sample items: assessment findings, scoring and the
// reasons behind EMT-level interventions.
import {q, mix} from './q.js';
const AAOS='Pollak (AAOS), Emergency Care and Transportation of the Sick and Injured', BRADY='Limmer & O’Keefe, Emergency Care', AHA='AHA BLS Provider Manual';
const ASSESS='Patient Assessment', BLS='Basic Life Support', TRAUMA='Trauma', MED='Medical Emergencies', PEDS='Pediatrics and Childbirth', ENV='Environmental Emergencies', SPEC='Special Situations';

export default {
 id:'emergency-medical-technician-1',
 event:'Emergency Medical Technician',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AAOS Emergency Care and Transportation of the Sick and Injured, Brady Emergency Care, and the AHA BLS Provider Manual',
 plan:[{area:ASSESS,weight:20},{area:BLS,weight:20},{area:TRAUMA,weight:16},{area:MED,weight:14},{area:PEDS,weight:16},{area:ENV,weight:10},{area:SPEC,weight:4}],
 questions:mix([
  q(ASSESS,'Which information is gathered during the scene size-up?','Hazards, mechanism of injury and number of patients',['Vital signs and the patient’s medical history','The patient’s chief complaint and allergies','Pupil size and level of consciousness'],'C','Scene size-up comes before patient contact: scene safety, standard precautions, mechanism of injury or nature of illness, number of patients and need for more resources.',AAOS),
  q(ASSESS,'A trauma patient has bright red blood spurting from a thigh wound. In the primary assessment, what is addressed first?','The bleeding',['The airway','Breathing adequacy','The pulse rate'],'A','Current EMS teaching uses an X-ABC approach: exsanguinating external hemorrhage is controlled first because a patient can bleed to death in minutes.',AAOS),
  q(ASSESS,'A patient opens his eyes only to pain, makes incomprehensible sounds and withdraws from pain. What is his Glasgow Coma Scale score?','8',['6','9','10'],'B','Eye opening to pain = 2, incomprehensible sounds = 2, withdrawal from pain = 4. Total = 8. A GCS of 8 or less usually means the patient cannot protect the airway.',AAOS),
  q(ASSESS,'A patient rescued from a house fire has a pulse oximeter reading of 99%. Why may this reading be misleading?','Carbon monoxide gives a falsely normal reading',['Smoke causes the device to read too low','Burns make the pulse too fast to read','Heat damages the device’s sensor'],'D','Pulse oximeters cannot tell oxygen from carbon monoxide bound to hemoglobin, so SpO₂ may look normal in CO poisoning. Give high-flow oxygen based on the situation.',AAOS),
  q(ASSESS,'In the OPQRST mnemonic for assessing pain, what does R stand for?','Region and radiation',['Rate and rhythm','Relief and response','Rest and recovery'],'C','OPQRST: Onset, Provocation/palliation, Quality, Region/Radiation, Severity, Time.',AAOS),
  q(ASSESS,'A patient with chest pain denies shortness of breath. Why should the EMT document this?','It is a pertinent negative',['It is part of the scene size-up','It replaces the need for vital signs','It is an objective finding'],'A','Pertinent negatives are expected signs or symptoms that are absent. They help other providers understand the patient’s condition.',BRADY),
  q(ASSESS,'How often should an unstable patient be reassessed during transport?','Every 5 minutes',['Every 10 minutes','Every 15 minutes','Only on arrival at the hospital'],'B','Unstable patients are reassessed at least every 5 minutes and stable patients at least every 15 minutes, or after every intervention.',AAOS),
  q(ASSESS,'An adult patient is breathing 6 times per minute with shallow chest rise. What should the EMT do?','Assist ventilations with a bag-mask device',['Apply a nasal cannula at 2 L/min','Apply a nonrebreather mask at 15 L/min','Place the patient in the recovery position'],'D','A rate of 6 with shallow breaths is inadequate breathing. Masks only supply oxygen to a patient who is breathing adequately; this patient needs positive-pressure ventilation.',AAOS),
  q(ASSESS,'Capillary refill is most reliable as a sign of perfusion in which patients?','Children under 6',['Older adults','Patients in cold weather','Smokers'],'A','In infants and young children, capillary refill reliably reflects perfusion. Age, cold, smoking and medications make it less reliable in adults.',AAOS),
  q(ASSESS,'A patient was ejected from a vehicle in a rollover crash. Which assessment approach is appropriate after the primary assessment?','A rapid full-body scan',['A focused exam of the chief complaint only','A full exam after arriving at the hospital','No exam until the patient is stable'],'C','A significant mechanism of injury calls for a rapid head-to-toe scan to find hidden life threats. A focused exam is used for isolated injuries with a minor mechanism.',AAOS),
  q(BLS,'How is an oropharyngeal airway (OPA) correctly sized?','From the corner of the mouth to the earlobe',['From the nostril to the earlobe','From the chin to the collarbone','From the lips to the angle of the jaw'],'B','An OPA should reach from the corner of the mouth to the tip of the earlobe (or the angle of the jaw). A nasopharyngeal airway is measured from the nostril to the earlobe.',AAOS),
  q(BLS,'A nasopharyngeal airway should NOT be used in a patient with which finding?','Clear nasal drainage after head trauma',['An intact, strong gag reflex','Clenched teeth during a seizure','A semiconscious level of response'],'D','Clear fluid from the nose after head injury suggests a skull base fracture; an NPA could enter the cranial vault. NPAs are useful for patients with a gag reflex or clenched teeth.',AAOS),
  q(BLS,'What is the maximum time an adult’s airway should be suctioned at one time?','15 seconds',['5 seconds','30 seconds','60 seconds'],'C','Suctioning removes oxygen along with secretions, so adults are suctioned no longer than 15 seconds at a time (less for children and infants), with oxygen between attempts.',AAOS),
  q(BLS,'At what flow rate is a nonrebreather mask used?','10–15 L/min',['1–6 L/min','6–8 L/min','20–25 L/min'],'A','The reservoir bag must stay inflated, which requires 10–15 L/min. A nasal cannula is used at 1–6 L/min.',AAOS),
  q(BLS,'Two EMTs are performing CPR on a 5-year-old child. What compression-to-ventilation ratio should they use?','15:2',['30:2','5:1','3:1'],'B','For children and infants, two rescuers use 15:2. A single rescuer uses 30:2. The 3:1 ratio is for newborns.',AHA),
  q(BLS,'An AED is used on a 6-year-old in cardiac arrest. Which pads are preferred?','Pediatric pads or a dose attenuator',['Adult pads placed on the back only','No pads; children are not defibrillated','Adult pads cut to a smaller size'],'D','Children under 8 should be defibrillated with pediatric pads or an attenuator if available. If not, adult pads are used, placed so they do not touch.',AHA),
  q(BLS,'Which technique opens the airway of an unresponsive patient with a suspected spinal injury?','Jaw-thrust maneuver',['Head tilt–chin lift','Tongue-jaw lift','Neck extension with a towel roll'],'A','The jaw thrust opens the airway without tilting the head. If it does not open the airway, a head tilt–chin lift is used, because an open airway takes priority.',AHA),
  q(BLS,'Which patient is the best candidate for continuous positive airway pressure (CPAP)?','An alert patient with CHF in respiratory distress',['An unresponsive patient who is not breathing','A patient with a blood pressure of 80/50 mm Hg','A patient with a suspected pneumothorax'],'C','CPAP helps alert patients who can follow commands and protect their airway, such as those with CHF or COPD. It is contraindicated with hypotension, pneumothorax or inadequate breathing.',AAOS),
  q(BLS,'Which finding shows that bag-mask ventilations are adequate?','Visible chest rise with each breath',['A bulging abdomen after each breath','A ventilation rate above 30 per minute','Air escaping around the mask'],'B','Adequate ventilation produces visible chest rise. A bulging abdomen means air is entering the stomach (gastric distention), often from breaths that are too forceful or fast.',AHA),
  q(BLS,'Why does the AHA recommend switching compressors about every 2 minutes during CPR?','Fatigue reduces compression quality',['The AED requires it to analyze','It allows the pulse to be checked','Compressions cause rib fractures after 2 minutes'],'A','Rescuers become fatigued within a couple of minutes, often without noticing, and compressions become shallower. Switching at each rhythm check keeps compressions effective.',AHA),
  q(TRAUMA,'Which finding suggests compensated shock in an adult trauma patient?','Rapid pulse with a normal blood pressure',['Low blood pressure with a slow pulse','Warm, dry, flushed skin','Pinpoint pupils with a slow pulse'],'D','In compensated shock, the body maintains blood pressure by increasing the heart rate and constricting vessels, causing pale, cool skin. A falling blood pressure is a late sign of decompensation.',AAOS),
  q(TRAUMA,'A patient with a chest injury has severe respiratory distress, distended neck veins and absent breath sounds on one side. What should be suspected?','Tension pneumothorax',['Simple rib fracture','Flail chest','Cardiac contusion'],'C','Air trapped in the pleural space under pressure collapses the lung and pushes on the heart and great vessels, reducing blood return. Tracheal deviation is a late sign.',AAOS),
  q(TRAUMA,'A section of a patient’s chest wall moves inward when the patient inhales. What does this describe?','Flail chest',['Normal accessory muscle use','Subcutaneous emphysema','Pericardial tamponade'],'B','When two or more adjacent ribs are broken in two or more places, the loose segment moves opposite the rest of the chest wall. Breathing is impaired and the lung beneath is often bruised.',AAOS),
  q(TRAUMA,'A patient with a head injury develops rising blood pressure, a slowing pulse and irregular breathing. These signs indicate:','Increased intracranial pressure',['Hypovolemic (hemorrhagic) shock','Spinal shock','A simple, mild concussion'],'A','This is Cushing’s triad, a late sign of increased intracranial pressure and possible brain herniation. Rapid transport and adequate ventilation are critical.',AAOS),
  q(TRAUMA,'Using the pediatric rule of nines, what percentage of body surface area does an infant’s entire head and neck represent?','18%',['9%','13.5%','27%'],'D','A young child’s head is proportionally larger, so it counts as 18% instead of the adult 9%. Each leg is correspondingly smaller (about 13.5%).',AAOS),
  q(TRAUMA,'Why is an unstable pelvic fracture a life-threatening injury?','It can cause massive internal bleeding',['It always damages the spinal cord','It blocks the airway','It prevents the patient from breathing'],'C','The pelvis surrounds large blood vessels, and fractures can cause severe hidden blood loss. A pelvic binder can help stabilize the pelvis and reduce bleeding.',AAOS),
  q(TRAUMA,'For a critical trauma patient, what is the goal for on-scene time?','10 minutes or less',['20 to 30 minutes','Until all splinting is complete','As long as needed for a full exam'],'B','Critically injured patients need surgery, which EMTs cannot provide. EMTs treat immediate life threats and aim to leave the scene within about 10 minutes.',AAOS),
  q(TRAUMA,'A traction splint is indicated for which injury?','An isolated midshaft femur fracture',['A fracture of the hip joint','A fracture near the knee','An open fracture of the ankle'],'D','Traction splints are used for isolated midshaft femur fractures. They are contraindicated for injuries to the hip, pelvis, knee or ankle on the same leg.',AAOS),
  q(MED,'Before giving oral glucose to a patient with low blood sugar, the EMT must confirm the patient:','Can swallow and protect their airway',['Has a blood glucose below 40 mg/dL','Has taken insulin within 1 hour','Is fully alert and oriented'],'A','Oral glucose is given to patients with an altered mental status and a history of diabetes only if they can swallow. Otherwise, aspiration is a risk.',AAOS),
  q(MED,'Which finding is a contraindication to helping a patient take nitroglycerin?','Recent use of an erectile dysfunction drug',['Chest pain lasting more than 5 minutes','A history of stable angina','A heart rate of 90 beats per minute'],'C','Drugs such as sildenafil combined with nitroglycerin can cause a severe drop in blood pressure. Low blood pressure is also a contraindication.',AAOS),
  q(MED,'The Cincinnati Prehospital Stroke Scale tests which three findings?','Facial droop, arm drift and speech',['Pupils, pulse and blood pressure','Grip strength, gait and vision','Headache, nausea and neck stiffness'],'B','The patient is asked to smile, hold both arms out with eyes closed and repeat a sentence. An abnormality in any one suggests a stroke.',AAOS),
  q(MED,'How does epinephrine reverse the effects of anaphylaxis?','It constricts vessels and dilates airways',['It blocks histamine from being released','It slows the heart to reduce swelling','It neutralizes the allergen in the blood'],'D','Epinephrine raises blood pressure by constricting vessels and relaxes the smooth muscle of the bronchioles, reversing shock and wheezing.',AAOS),
  q(MED,'An EMT assists a patient having an asthma attack with a prescribed albuterol inhaler. How does albuterol work?','It relaxes the smooth muscle of the bronchioles',['It reduces airway inflammation over several days','It thins mucus in the lungs','It speeds the breathing rate'],'A','Albuterol is a short-acting beta-2 agonist that quickly dilates the bronchioles. Inhaled steroids reduce inflammation over time but do not stop an acute attack.',AAOS),
  q(MED,'A patient has stopped seizing but is confused and drowsy. What is this phase called?','Postictal state',['Aura','Tonic phase','Status epilepticus'],'C','The postictal phase follows a seizure, with confusion and fatigue that improve over minutes to hours. An aura is a warning before some seizures.',AAOS),
  q(MED,'A patient with a history of heart failure is sitting upright, very short of breath, with crackles and pink, frothy sputum. What is most likely?','Pulmonary edema',['Pneumothorax','Asthma attack','Pulmonary embolism'],'B','When the left ventricle fails, fluid backs up into the lungs. Crackles and pink, frothy sputum are classic signs. CPAP and high-flow oxygen help.',BRADY),
  q(PEDS,'What three components make up the pediatric assessment triangle?','Appearance, work of breathing and circulation to the skin',['Pulse, blood pressure and respiratory rate','Airway, breathing and circulation','Level of consciousness, pupils and motor response'],'D','The pediatric assessment triangle is a quick visual “from the doorway” check that helps determine how sick a child is before touching them.',AAOS),
  q(PEDS,'A 4-year-old is sitting upright, leaning forward and drooling, with a high fever. Why should the EMT avoid examining the child’s throat?','It may trigger complete airway blockage',['It will make the child’s fever worse','It spreads the infection to the EMT','It usually causes the child to vomit'],'A','These are signs of epiglottitis. Agitating the child or putting anything in the mouth can trigger complete airway obstruction. Keep the child calm and transport.',AAOS),
  q(PEDS,'Using the formula 70 + (2 × age in years), what is the minimum acceptable systolic blood pressure for a 4-year-old?','78 mm Hg',['70 mm Hg','74 mm Hg','86 mm Hg'],'C','70 + (2 × 4) = 78 mm Hg. A systolic pressure below this in a child aged 1 to 10 suggests hypotension and decompensated shock.',AAOS),
  q(PEDS,'During labor, the EMT sees the baby’s head bulging at the vaginal opening with each contraction. What should be done?','Prepare to deliver on scene',['Transport immediately to the hospital','Have the mother hold her legs together','Place the mother on her left side and wait'],'B','Crowning means birth is imminent. Delivery should take place at the scene rather than in a moving ambulance.',AAOS),
  q(PEDS,'During delivery, the umbilical cord comes out before the baby (prolapsed cord). What should the EMT do?','Lift the baby off the cord with gloved fingers',['Push the cord back into the vagina','Pull gently on the cord to speed delivery','Clamp and cut the cord immediately'],'D','The baby’s head can compress the cord and cut off oxygen. The EMT lifts the presenting part off the cord, positions the mother knees-to-chest or with hips elevated, gives oxygen and transports rapidly.',AAOS),
  q(PEDS,'When is the APGAR score assessed for a newborn?','At 1 and 5 minutes after birth',['Immediately and at 30 minutes','Only after the placenta is delivered','At 10 and 20 minutes after birth'],'A','APGAR (appearance, pulse, grimace, activity, respiration) is scored at 1 and 5 minutes. Resuscitation is never delayed to calculate the score.',AAOS),
  q(PEDS,'A newborn’s heart rate stays below 60 per minute despite 30 seconds of effective ventilation. What compression-to-ventilation ratio is used?','3:1',['15:2','30:2','5:1'],'C','Newborn resuscitation uses 3 compressions to 1 ventilation, about 120 events per minute, because newborn arrest is usually caused by a lack of oxygen.',AHA),
  q(PEDS,'After delivery of the placenta, the mother is bleeding heavily. What should the EMT do?','Massage the uterus through the abdomen',['Pack the vagina with gauze','Have her stand and walk to the ambulance','Place her in a sitting position'],'B','Fundal massage helps the uterus contract and compress bleeding vessels. Breastfeeding also releases hormones that help the uterus contract. Never pack the vagina.',AAOS),
  q(ENV,'Which treatment is most important for a patient with exertional heat stroke?','Rapid cooling, ideally cold-water immersion',['Warm fluids by mouth','Cover with a blanket to prevent shivering','Wait for EMS to arrive before cooling'],'D','Heat stroke is a true emergency with altered mental status and very high body temperature. The faster the body is cooled, the better the chance of survival.',AAOS),
  q(ENV,'When checking for a pulse in a patient with severe hypothermia, how long should the EMT feel for it?','30–45 seconds',['5 seconds','10 seconds','2 minutes'],'A','A cold, slow heart may have a very slow, weak pulse. Checking longer prevents starting CPR on a patient who has a pulse, since compressions could trigger ventricular fibrillation.',AAOS),
  q(ENV,'A scuba diver develops joint pain and dizziness several hours after a dive. What condition is most likely?','Decompression sickness',['Air embolism','Nitrogen narcosis','Barotrauma of the ear'],'B','Nitrogen bubbles form in the blood and tissues when a diver ascends too fast, causing joint pain (“the bends”) and neurologic signs, often hours later. Air embolism usually causes symptoms immediately on surfacing.',AAOS),
  q(ENV,'A patient lying on cold, wet ground loses heat directly to the ground. Which mechanism of heat loss is this?','Conduction',['Radiation','Convection','Evaporation'],'C','Conduction is direct transfer of heat to a colder object; wet clothing increases it. Convection is heat loss to moving air or water, and radiation is heat lost to the environment without contact.',AAOS),
  q(ENV,'A swimmer is found floating face down after diving into shallow water. What must the EMT suspect and protect?','A spinal injury',['A shoulder dislocation','A ruptured eardrum','A broken wrist'],'D','Diving into shallow water commonly causes cervical spine injury. The patient is kept in line while being removed from the water.',AAOS),
  q(SPEC,'Using START triage, how is an adult tagged who cannot walk and is breathing 36 times per minute?','Immediate (red)',['Delayed (yellow)','Minor (green)','Expectant (black)'],'A','In START, adults breathing more than 30 per minute are tagged immediate. Walking wounded are tagged minor (green).',AAOS),
  q(SPEC,'EMTs arrive at a tanker truck crash with a leaking unknown substance. Where should they stage?','Uphill and upwind at a safe distance',['Downwind to see the vapor clearly','As close as possible to begin rescue','Downhill so runoff can be seen'],'B','Staying uphill and upwind protects responders from vapors and runoff. The Emergency Response Guidebook helps identify the material and safe distances.',AAOS)
 ],29)
};
